import sys

def main():
    data = sys.stdin.read().splitlines()
    if not data:
        return
    n_line = data[0].strip()
    if not n_line:
        return
    n = int(n_line)
    if n <= 0:
        # No output for non‑positive size
        return
    # Ensure the second line exists; if not, treat as empty list
    if len(data) < 2:
        arr = []
    else:
        arr = list(map(int, data[1].split()))
    # Reverse the array
    rev = arr[::-1]
    # Print space‑separated values, no trailing space
    print(' '.join(map(str, rev)))

if __name__ == "__main__":
    main()
